UPDATE tb_building
building_no = #{buildingDto.buildingNo}, use_volume = #{buildingDto.useVolume}, use_volume_unit= #{buildingDto.useVolumeUnit}, use_area = #{buildingDto.useArea}, use_area_unit = #{buildingDto.useAreaUnit}, building_orientation = #{buildingDto.buildingOrientation}, remark = #{buildingDto.remark}, last_updated_user = #{buildingDto.updateUser}, warehouse_id = #{buildingDto.warehouseId}, pid_route = #{buildingDto.pidRoute}, building_name = #{buildingDto.buildingName}, site_name = #{buildingDto.siteName}, building_type = #{buildingDto.buildingType}, principal_id = #{buildingDto.principalId}, principal_name = #{buildingDto.principalName}, last_updated_time = sysdate
