UPDATE tb_floor
floor_no = #{floorDto.floorNo}, is_partition= #{floorDto.isPartition}, remark = #{floorDto.remark}, last_updated_user = #{floorDto.updateUser}, building_id = #{floorDto.buildingId}, pid_route = #{floorDto.pidRoute}, floor_name = #{floorDto.floorName}, site_name = #{floorDto.siteName}, floor_type = #{floorDto.floorType}, principal_id = #{floorDto.principalId}, principal_name = #{floorDto.principalName}, last_updated_time = sysdate
