UPDATE tb_ware_area
area_no = #{wareAreaDto.areaNo}, last_updated_user =#{wareAreaDto.updateUser}, floor_id =#{wareAreaDto.floorId}, pid_route =#{wareAreaDto.pidRoute}, area_name = #{wareAreaDto.areaName}, site_name = #{wareAreaDto.siteName}, ware_area_type = #{wareAreaDto.wareAreaType}, remark = #{wareAreaDto.remark}, principal_id = #{wareAreaDto.principalId}, principal_name = #{wareAreaDto.principalName}, last_updated_time = sysdate
WHERE id = #{wareAreaDto.id}

UPDATE tb_stack
